WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK;
ALTER SESSION SET CONTAINER=FREEPDB1;
DECLARE n NUMBER;BEGIN
 SELECT COUNT(*) INTO n FROM ALL_TABLES WHERE OWNER='CF_ELIGIBILITY' AND TABLE_NAME='LENDER_PRODUCT_HEAD';
 IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CF_ELIGIBILITY.LENDER_PRODUCT_HEAD(PRODUCT_ID VARCHAR2(36) PRIMARY KEY,CURRENT_VERSION NUMBER(10) NOT NULL)';END IF;
 SELECT COUNT(*) INTO n FROM ALL_TABLES WHERE OWNER='CF_ELIGIBILITY' AND TABLE_NAME='LENDER_RULE_CHANGE';
 IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CF_ELIGIBILITY.LENDER_RULE_CHANGE(PRODUCT_ID VARCHAR2(36) NOT NULL,RULE_VERSION NUMBER(10) NOT NULL,ACTOR_ID VARCHAR2(100) NOT NULL,CHANGED_AT TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,REASON VARCHAR2(500 CHAR) NOT NULL,RETRY_KEY VARCHAR2(100) UNIQUE NOT NULL,REQUEST_HASH VARCHAR2(64) NOT NULL,PRIMARY KEY(PRODUCT_ID,RULE_VERSION))';END IF;
 SELECT COUNT(*) INTO n FROM ALL_TABLES WHERE OWNER='CF_APPLICATION' AND TABLE_NAME='CF_APPLICATION_CORRECTIONS';
 IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CF_APPLICATION.CF_APPLICATION_CORRECTIONS(OPERATION_ID VARCHAR2(36) PRIMARY KEY,APPLICATION_ID VARCHAR2(36) NOT NULL,SELLER_ID VARCHAR2(100) NOT NULL,ACTOR_ID VARCHAR2(100) NOT NULL,RETRY_KEY VARCHAR2(100) NOT NULL,REQUEST_HASH VARCHAR2(64) NOT NULL,EXPECTED_REVISION NUMBER(10) NOT NULL,NEW_REVISION NUMBER(10) NOT NULL,BEFORE_JSON CLOB NOT NULL,AFTER_JSON CLOB NOT NULL,STATUS VARCHAR2(20) DEFAULT ''PENDING'' NOT NULL,ATTEMPTS NUMBER(10) DEFAULT 0 NOT NULL,CLAIM_TOKEN VARCHAR2(36),LEASE_UNTIL TIMESTAMP WITH TIME ZONE,NEXT_ATTEMPT_AT TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,LAST_ERROR VARCHAR2(100),CREATED_AT TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,UPDATED_AT TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,UNIQUE(APPLICATION_ID,RETRY_KEY))';END IF;
END;
/
MERGE INTO CF_ELIGIBILITY.LENDER_PRODUCT_HEAD H USING (SELECT PRODUCT_ID,MAX(RULE_VERSION) V FROM CF_ELIGIBILITY.LENDER_PRODUCT_RULE GROUP BY PRODUCT_ID) R ON (H.PRODUCT_ID=R.PRODUCT_ID) WHEN NOT MATCHED THEN INSERT(PRODUCT_ID,CURRENT_VERSION) VALUES(R.PRODUCT_ID,R.V);
ALTER TABLE CF_AUTH.CF_AUTH_USERS DROP CONSTRAINT CK_CF_AUTH_ROLE;
ALTER TABLE CF_AUTH.CF_AUTH_USERS ADD CONSTRAINT CK_CF_AUTH_ROLE CHECK(USER_ROLE IN('ADMIN','SELLER','MARKETPLACE','VERIFICATION_SERVICE','ELIGIBILITY_SERVICE','ORCHESTRATION_SERVICE','INTEGRATION_SERVICE','LENDER_SERVICE','LENDER_OFFICER','APPLICATION_SERVICE'));
COMMIT;
EXIT;
